-- ============================================================================
-- Migration 1093: the multi-spindle machines' limits and slide layout
-- ============================================================================
-- Generated by scripts/generate-multi-spindle-machines-migration.js; re-run it and diff instead of editing.
--
-- The 15 Simultaneous Turning machines of memory/machining/machine/simultaneous_turning_usa.csv (CNC multi-spindles with 6 or 8 spindles and twin-spindle
-- turning centers; HR Rates class simultaneous_turning) were seeded for USA (migration 738) and India (829) with their rates, setup and index times
-- (788). Their limits and slide layout stayed in the CSV: max_diameter_mm and max_length_mm were empty (migration 755 filled them for the
-- lathes only), so the machine selector could not check a part's bar against any of them and chose the cheapest hourly rate; and no station
-- plan could be laid out, because which spindle carries which slide, and which spindles do the back work, was nowhere.
--
-- Written by machine name to both locations' rows (Multi-Spindle Machining, user decision 2026-11-20):
--   typed  max_diameter_mm, max_length_mm (limits.*, the bar capacity and the part length the machine takes)
--   specs  process_type; od_slide_spindles, end_slide_spindles, live_tooling_spindles, back_work_spindles (slide_configuration.*: a spindle
--          listed twice carries two slides of the kind, the twin turrets of a sub-spindle turning center); spindle_speed_rpm,
--          spindle_power_kw, travel_z_mm, max_mill_tool_diameter_mm, live_tooling_speed_rpm, rapid_traverse_mm_per_min (limits.*, rates.*);
--          base_part_setup_time_hr, part_eject_time_s, tool_positioning_time_s, dull_tool_replace_time_s, spotting_time_s,
--          countersinking_time_s (time.*); approach_depart_mm, can_gun_drill (other.*)
--
-- Idempotent: the same values are re-set.
-- Verify: SELECT location, count(*), count(max_diameter_mm), count(specs->'od_slide_spindles') FROM mhr_records
--           WHERE machine_class = 'simultaneous_turning' GROUP BY 1 ORDER BY 1;
-- ============================================================================

UPDATE mhr_records m SET
  max_diameter_mm = v.max_diameter_mm,
  max_length_mm = v.max_length_mm,
  specs = COALESCE(m.specs, '{}'::jsonb) || jsonb_build_object(
    'process_type', v.process_type,
    'od_slide_spindles', v.od_slide_spindles, 'end_slide_spindles', v.end_slide_spindles,
    'live_tooling_spindles', v.live_tooling_spindles, 'back_work_spindles', v.back_work_spindles,
    'spindle_speed_rpm', v.spindle_speed_rpm, 'spindle_power_kw', v.spindle_power_kw, 'travel_z_mm', v.travel_z_mm,
    'max_mill_tool_diameter_mm', v.max_mill_tool_diameter_mm, 'live_tooling_speed_rpm', v.live_tooling_speed_rpm,
    'rapid_traverse_mm_per_min', v.rapid_traverse_mm_per_min, 'base_part_setup_time_hr', v.base_part_setup_time_hr,
    'part_eject_time_s', v.part_eject_time_s, 'tool_positioning_time_s', v.tool_positioning_time_s,
    'dull_tool_replace_time_s', v.dull_tool_replace_time_s, 'spotting_time_s', v.spotting_time_s,
    'countersinking_time_s', v.countersinking_time_s, 'approach_depart_mm', v.approach_depart_mm, 'can_gun_drill', v.can_gun_drill),
  updated_at = now()
FROM (VALUES
  ($str$DMG Mori GMC25ISM-6$str$, $str$CNC Multi-Spindle$str$, 25, 120, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[6]'::jsonb, 6000, 17.2, 70, 50.8, 6000, 30000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Dooson Puma TT2500SY$str$, $str$CNC Turning Center with Sub Spindle$str$, 42, 80, '[1,1,2,2]'::jsonb, '[1,2]'::jsonb, '[1,2]'::jsonb, '[2]'::jsonb, 7000, 20.13, 80, 50.8, 5000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$HAAS DS-30Y$str$, $str$CNC Turning Center with Sub Spindle$str$, 76, 584, '[1,1,2,2]'::jsonb, '[1,2]'::jsonb, '[1,2]'::jsonb, '[2]'::jsonb, 4500, 22.37, 584, 50.8, 6000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Index MS16C-6$str$, $str$CNC Multi-Spindle$str$, 22, 70, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[6]'::jsonb, 10000, 15, 70, 50.8, 10000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Index MS22-8$str$, $str$CNC Multi-Spindle$str$, 24, 85, '[1,2,3,4,5,6,7,8]'::jsonb, '[1,2,3,4,5,6,7,8]'::jsonb, '[1,2,3,4,5,6,7,8]'::jsonb, '[7,8]'::jsonb, 10000, 15, 85, 50.8, 10000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Index MS32-6$str$, $str$CNC Multi-Spindle$str$, 32, 100, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[6]'::jsonb, 8000, 19, 100, 50.8, 8000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Index MS40-8$str$, $str$CNC Multi-Spindle$str$, 40, 120, '[1,2,3,4,5,6,7,8]'::jsonb, '[1,2,3,4,5,6,7,8]'::jsonb, '[1,2,3,4,5,6,7,8]'::jsonb, '[7,8]'::jsonb, 7000, 24, 120, 50.8, 8000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Tsugami M08SY$str$, $str$CNC Turning Center with Sub Spindle$str$, 65, 380, '[1,1,2,2]'::jsonb, '[1,2]'::jsonb, '[1,2]'::jsonb, '[2]'::jsonb, 4500, 11, 100, 50.8, 5000, 27000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Virtual CNC Multi-Spindle, 6 Spindles, Large$str$, $str$CNC Multi-Spindle$str$, 90, 205, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[6]'::jsonb, 10000, 24, 120, 50.8, 10000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Virtual CNC Multi-Spindle, 6 Spindles, Small$str$, $str$CNC Multi-Spindle$str$, 25.4, 80, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[1,2,3,4,5,6]'::jsonb, '[6]'::jsonb, 6000, 15, 80, 50.8, 6000, 12000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Virtual CNC Multi-Spindle, 8 Spindles, Large$str$, $str$CNC Multi-Spindle$str$, 90, 205, '[1,2,3,4,5,6,7,8]'::jsonb, '[1,2,3,4,5,6,7,8]'::jsonb, '[1,2,3,4,5,6,7,8]'::jsonb, '[7,8]'::jsonb, 10000, 30, 120, 50.8, 10000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Virtual CNC Multi-Spindle, 8 Spindles, Small$str$, $str$CNC Multi-Spindle$str$, 25.4, 80, '[1,2,3,4,5,6,7,8]'::jsonb, '[1,2,3,4,5,6,7,8]'::jsonb, '[1,2,3,4,5,6,7,8]'::jsonb, '[7,8]'::jsonb, 8000, 20, 80, 50.8, 8000, 12000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Virtual CNC Turning Center with Sub Spindle, Large$str$, $str$CNC Turning Center with Sub Spindle$str$, 82, 1000, '[1,1,2,2]'::jsonb, '[1,2]'::jsonb, '[1,2]'::jsonb, '[2]'::jsonb, 7000, 28, 600, 50.8, 10000, 30000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Virtual CNC Turning Center with Sub Spindle, Medium$str$, $str$CNC Turning Center with Sub Spindle$str$, 65, 450, '[1,1,2,2]'::jsonb, '[1,2]'::jsonb, '[1,2]'::jsonb, '[2]'::jsonb, 4500, 15, 300, 50.8, 6000, 27000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true),
  ($str$Virtual CNC Turning Center with Sub Spindle, Small$str$, $str$CNC Turning Center with Sub Spindle$str$, 25.4, 150, '[1,1,2,2]'::jsonb, '[1,2]'::jsonb, '[1,2]'::jsonb, '[2]'::jsonb, 3500, 11, 100, 50.8, 5000, 24000, 0.07, 1, 0.9, 60, 1, 1, 2.54, true)
) AS v(machine_name, process_type, max_diameter_mm, max_length_mm, od_slide_spindles, end_slide_spindles, live_tooling_spindles,
       back_work_spindles, spindle_speed_rpm, spindle_power_kw, travel_z_mm, max_mill_tool_diameter_mm, live_tooling_speed_rpm,
       rapid_traverse_mm_per_min, base_part_setup_time_hr, part_eject_time_s, tool_positioning_time_s, dull_tool_replace_time_s,
       spotting_time_s, countersinking_time_s, approach_depart_mm, can_gun_drill)
WHERE m.machine_class = 'simultaneous_turning' AND m.machine_name = v.machine_name;

DO $ms_check$
DECLARE bare text[];
BEGIN
  SELECT array_agg(location || ': ' || machine_name ORDER BY location, machine_name) INTO bare FROM mhr_records
   WHERE machine_class = 'simultaneous_turning' AND (max_diameter_mm IS NULL OR max_length_mm IS NULL OR NOT specs ? 'od_slide_spindles');
  IF bare IS NOT NULL THEN RAISE EXCEPTION 'Multi-spindle machines still without limits or slide layout (not in memory/machining/machine/simultaneous_turning_usa.csv): %', bare; END IF;
END $ms_check$;

NOTIFY pgrst, 'reload schema';
